def transform(grid):
    """Complete the diagonal-periodic color pattern encoded by the input stripes."""
    h, w = len(grid), len(grid[0])
    diagonal_colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in diagonal_colors and diagonal_colors[d] != color:
                    raise ValueError("Input has inconsistent colors on a diagonal")
                diagonal_colors[d] = color

    # The pattern's period is the smallest period that consistently assigns a
    # color to every residue class represented by the observed diagonals.
    for period in range(1, max(h, w) + 1):
        motif = {}
        valid = True
        for d, color in diagonal_colors.items():
            residue = d % period
            if residue in motif and motif[residue] != color:
                valid = False
                break
            motif[residue] = color
        if valid and len(motif) == period:
            return [[motif[(c-r) % period] for c in range(w)] for r in range(h)]
    raise ValueError("Could not infer a fully specified diagonal period")
